package cn.huankan.collector;
import java.util.*;import java.math.BigDecimal;import java.time.LocalDate;import java.nio.charset.StandardCharsets;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.core.*;
public class BlsSourceAdapter implements SourceAdapter {
 public static final String URL="https://api.bls.gov/publicAPI/v1/timeseries/data/";
 public record Observation(String series,LocalDate date,String period,String rawValue,BigDecimal value,JsonNode footnotes,String releaseStatus,JsonNode payload,String literal){}
 public static List<Observation> observations(byte[] bytes){try{var mapper=new ObjectMapper().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);var root=mapper.readTree(bytes);if(!"REQUEST_SUCCEEDED".equals(root.path("status").asText()))throw new IllegalArgumentException("BLS_BUSINESS_"+root.path("status").asText("MISSING")+":"+root.path("message"));if(!root.path("Results").path("series").isArray()||root.path("Results").path("series").isEmpty())throw new IllegalArgumentException("BLS_EMPTY_SERIES");String raw=new String(bytes,StandardCharsets.UTF_8);var literals=new ArrayList<String>();try(var parser=mapper.getFactory().createParser(raw)){while(parser.nextToken()!=null){if(parser.currentToken()==JsonToken.FIELD_NAME&&parser.currentName().equals("data")&&parser.nextToken()==JsonToken.START_ARRAY){while(parser.nextToken()!=JsonToken.END_ARRAY){if(parser.currentToken()!=JsonToken.START_OBJECT)throw new IllegalArgumentException("BLS_BAD_ROW");int start=(int)parser.currentTokenLocation().getCharOffset();mapper.readTree(parser);int end=(int)parser.currentLocation().getCharOffset();literals.add(raw.substring(start,end));}}}}var result=new ArrayList<Observation>();Set<String> keys=new HashSet<>();int index=0;
 for(var series:root.path("Results").path("series")){String id=series.path("seriesID").asText();if(!id.matches("[A-Z0-9]{5,30}")||!series.path("data").isArray())throw new IllegalArgumentException("BLS_INVALID_SERIES");for(var row:series.path("data")){String literal=literals.get(index++),period=row.path("period").asText();if(!period.matches("M(0[1-9]|1[0-3])"))throw new IllegalArgumentException("BLS_UNSUPPORTED_PERIOD");if(period.equals("M13"))continue;int year=Integer.parseInt(row.path("year").asText());if(year<1900||year>2100)throw new IllegalArgumentException("BLS_INVALID_YEAR");LocalDate date=LocalDate.of(year,Integer.parseInt(period.substring(1)),1);if(!keys.add(id+":"+date))throw new IllegalArgumentException("BLS_DUPLICATE_OBSERVATION");String value=row.path("value").asText();BigDecimal number=value.equals("-")||value.isBlank()?null:new BigDecimal(value);JsonNode notes=row.path("footnotes");if(!notes.isArray())throw new IllegalArgumentException("BLS_MISSING_FOOTNOTES");String status="UNKNOWN";for(var n:notes){String text=n.path("text").asText().toLowerCase(Locale.ROOT);if(n.path("code").asText().equals("P")||text.contains("preliminary"))status="PRELIMINARY";else if(!status.equals("PRELIMINARY")&&text.contains("revis"))status="REVISED_NOTE";}result.add(new Observation(id,date,period,value,number,notes,status,row,literal));}}
 if(result.isEmpty())throw new IllegalArgumentException("BLS_NO_MONTHLY_OBSERVATIONS");return result;
 }catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("BLS_PARSE_FAILURE",e);}}
 public List<Item> parse(byte[] bytes){return observations(bytes).stream().map(o->new Item(o.series()+":"+o.date(),o.series()+" · "+o.date()+" · "+o.rawValue()+" · "+o.footnotes(),URL,null,"美国官方宏观数据")).toList();}
}
